package com.franco.desco.domain.campaign;import java.math.BigDecimal;import java.time.Instant;import java.time.LocalDate;import java.util.List;
public final class CampaignModels{private CampaignModels(){}public record Summary(Long campaniaVentaId,String codigo,String nombre,LocalDate fechaInicio,LocalDate fechaFin,String estadoProceso,Long asociacionId,String asociacion,Long empresaCompradoraId,String comprador,String observacion,Long participantesActivos,Long operativos){}public record Participant(Long participacionId,String estadoParticipacion,Long socioId,String numeroDocumento,String socioNombre){}public record Operation(Long operativoVentaId,String codigo,Instant fechaInicioProgramada,Instant fechaFinProgramada,Instant fechaInicioReal,Instant fechaFinReal,Integer cantidadJabasRecibidas,String estadoProceso,String observacion){}public record Price(Long precioComercialId,Long operativoVentaId,Integer variedadPaltaId,Long condicionComercialId,BigDecimal precio,String moneda,String unidadMedida,Instant fechaVigenciaDesde,Instant fechaVigenciaHasta,Integer version){}public record Detail(Summary campania,List<Participant>participantes,List<Operation>operativos,List<Price>precios){public Detail{participantes=participantes==null?List.of():List.copyOf(participantes);operativos=operativos==null?List.of():List.copyOf(operativos);precios=precios==null?List.of():List.copyOf(precios);}}}
